void doDrawUnit(@Nonnull Unit unit, @Nonnull Canvas canvas, @Nonnull UnitDrawerConfig config, boolean srcOut) {
    Matrix matrix = config.mSceneMatrix;
    canvas.save();
    UnitAssets.EdgeKey edgeKey = new UnitAssets.EdgeKey();
    for (UEdge uEdge : unit.getEdges()) {
        if ("head".equals(uEdge.mEnd.mSemanticName) && unit.getFaceId() != -1) {
            edgeKey.reset();
            edgeKey.faceId = unit.getFaceId();
        } else {
            edgeKey.unitName = SceneHelper.removeNumber(unit.getName());
            edgeKey.start = uEdge.mStart.getId();
            edgeKey.end = uEdge.mEnd.getId();
            edgeKey.flipped = unit.isFlipped();
            edgeKey.faceId = -1;
        }
        UnitAssets.EdgeAsset drawable = unit.getScene().getDrawable(edgeKey, unit.getAssetsState());
        if (drawable != null) {
            float scale = drawable.x_offset * unit.getScale();
            float scale2 = drawable.y_offset * unit.getScale();
            Matrix matrixOps = UIMatrices.ops();
            matrixOps.reset();
            float angle = uEdge.getAngle();
            if (unit.isFlipped() && !drawable.nativeFlipped) {
                matrixOps.setScale(unit.getScale(), -unit.getScale());
                matrixOps.postTranslate(uEdge.mStart.x + scale, uEdge.mStart.y - scale2);
            } else {
                matrixOps.setScale(unit.getScale(), unit.getScale());
                matrixOps.postTranslate(uEdge.mStart.x + scale, uEdge.mStart.y + scale2);
            }
            matrixOps.postRotate(angle, uEdge.mStart.x, uEdge.mStart.y);
            BonePictureStretch.apply(matrixOps, unit, uEdge);
            if (config.mDrawEffect != null) {
                config.mDrawEffect.applyPartDrawOffset(matrixOps, unit, uEdge);
            }
            matrixOps.postConcat(matrix);
            canvas.setMatrix(matrixOps);
            int alpha = this.mOpsPaint.getAlpha();
            if (config.mDrawEffect != null) {
                this.mOpsPaint.setAlpha(Math.round(config.mDrawEffect.getPartAlpha(unit) * alpha));
            }
            if (srcOut) {
                this.mOpsPaint.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.SRC_OUT));
                this.mOpsPaint.setStyle(Paint.Style.FILL);
                this.mOpsPaint.setColor(0);
                canvas.drawBitmap(drawable.bitmap, 0.0f, 0.0f, this.mOpsPaint);
                this.mOpsPaint.setXfermode(null);
                this.mOpsPaint.setColor(-65536);
            } else {
                canvas.drawBitmap(drawable.bitmap, 0.0f, 0.0f, this.mOpsPaint);
            }
            this.mOpsPaint.setAlpha(alpha);
        }
    }
    canvas.restore();
}
